style.css:
@-moz-document domain("youtube.com"), domain("music.youtube.com") {
/* ------------ BACKGROUND LAYER ------------ */
    html::before {
        content: "" !important;
        position: fixed !important;
        inset: 0 !important;
        z-index: -9999 !important;   /* behind everything */
        pointer-events: none !important;
        background-image: url("https://i.postimg.cc/ZKNxqzyJ/HACKLORD.jpg") !important;
        background-repeat: no-repeat !important;
        background-position: center center !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        opacity: 1 !important;
    }

    /* ------------ Main YouTube containers transparent ------------ */
    html, body, ytd-app, ytd-music-app, #page-manager, ytd-page-manager,
    #content, #primary, #secondary, ytd-watch-flexy, ytd-browse,
    ytmusic-player-page, ytmusic-shelf-renderer, #player, #movie_player {
        background: transparent !important;
        background-image: none !important;
    }

    /* Masthead & overlays transparent */
    ytd-masthead, ytmusic-nav-bar, ytmusic-header-renderer,
    #masthead-container, ytd-guide-renderer, #guide {
        background-color: transparent !important;
        background-image: none !important;
    }

    /* ------------ Neon progress bar ------------ */
    .ytp-progress-bar, .ytp-load-progress { background-color: #000 !important; }       /* track */
    .ytp-play-progress, .ytp-hover-progress { background-color: #39FF14 !important; }  /* neon fill */

    /* Small translucency for player controls */
    .ytp-chrome-bottom, .ytp-chrome-top { background-color: rgba(0,0,0,0.15) !important; }

    /* ------------ Neon logo ------------ */
    ytd-topbar-logo-renderer svg, #logo-icon-container svg, *[id*="logo"] svg {
        fill: #39FF14 !important;
        stroke: #000 !important;
        stroke-width: 1px !important;
    }

    ytd-topbar-logo-renderer yt-icon#logo-text,
    *[id*="logo-text"], *[class*="logo-text"] {
        color: #39FF14 !important;
        -webkit-text-stroke: 1px #000 !important;
        text-shadow: 0 0 5px #39FF14, 0 0 10px #39FF14 !important;
        font-family: "Forsaken", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial !important;
        font-weight: 700 !important;
    }
}
